const accountSyncRoute=require('./account-sync-fixture.cjs');
'use strict';
const {test,afterEach}=require('node:test'),assert=require('node:assert/strict'),path=require('node:path');
const {chromium,executablePath}=require('../scripts/codex/browser.cjs');
const {serveBrowserFixture}=require('./browser-origin.cjs');
const providerFixtures=[];
async function installProvider(context,fixture){const net=await accountSyncRoute.installFetch(context,fixture);providerFixtures.push(net);return net;}
afterEach(t=>{const nets=providerFixtures.splice(0);if(nets.length){assert(nets.some(net=>net.intercepted>0),'this scenario must exercise its provider fixture');for(const net of nets)assert.equal(net.nativeSupabaseRequests,0,'provider fixture must prevent native Supabase requests');t.diagnostic('provider intercepted='+nets.map(net=>net.intercepted).join(',')+'; nativeSupabaseRequests=0');}});
async function overflowComposerProof(page,form,sendCount){
 const before=await sendCount(),editor=form.locator('[data-chat-editor]');await editor.fill('x'.repeat(1999));await editor.press('End');await editor.evaluate(e=>{e.dispatchEvent(new CompositionEvent('compositionstart',{bubbles:true}));document.execCommand('insertText',false,'かな');e.dispatchEvent(new CompositionEvent('compositionend',{bubbles:true,data:'かな'}));});
 assert.equal((await form.locator('textarea').inputValue()).length,2001);assert.equal(await editor.textContent(),await form.locator('textarea').inputValue());assert.equal(await form.locator('[type=submit]').isDisabled(),true);
 const proof=await form.evaluate(f=>{const e=f.querySelector('[data-chat-editor]'),node=e.firstChild,status=f.nextElementSibling;e.focus();getSelection().setBaseAndExtent(node,2,node,7);const selected=getSelection().toString();PlayroomChatComponents.resize(f,true);PlayroomChatComponents.resize(f,false);const r=status.getBoundingClientRect();return {nodeSame:e.firstChild===node,selected:getSelection().toString()===selected,described:e.getAttribute('aria-describedby').split(/\s+/).includes(status.id),invalid:e.getAttribute('aria-invalid'),visible:r.width>0&&r.height>0&&r.top>=0&&r.bottom<=innerHeight+1,message:status.textContent,nativeValid:f.checkValidity()};});
 assert.deepEqual(proof,{nodeSame:true,selected:true,described:true,invalid:'true',visible:true,message:'Не более 2000 символов. Сократите сообщение.',nativeValid:true});
 await editor.press('Enter');await form.evaluate(f=>{f.requestSubmit();f.requestSubmit();});await page.evaluate(()=>new Promise(requestAnimationFrame));assert.equal(await sendCount(),before,'invalid Enter/requestSubmit must not reach the owning sender');assert.equal((await form.locator('textarea').inputValue()).length,2001,'invalid attempt retains full draft');assert.equal(await editor.evaluate(e=>getSelection().toString()),'xxxxx','invalid submit preserves editor selection');
 await editor.press('End');await editor.press('Backspace');assert.equal((await form.locator('textarea').inputValue()).length,2000);assert.equal(await form.locator('[type=submit]').isEnabled(),true);await editor.press('Control+z');assert.equal((await form.locator('textarea').inputValue()).length,2001);assert.equal(await form.locator('[type=submit]').isDisabled(),true);await editor.press('Control+Shift+z');assert.equal((await form.locator('textarea').inputValue()).length,2000);assert.equal(await form.locator('[type=submit]').isEnabled(),true);await editor.fill('');
}
async function openProfileAccount(page){
 await page.waitForFunction(()=>document.querySelector('#profile-form')||globalThis.PlayroomAppBridge?.profile?.());
 if(await page.locator('#profile-form').count()){await page.locator('#profile-form [name=playerName]').fill('Игрок');await page.locator('#profile-form').evaluate(form=>form.requestSubmit());await page.locator('#profile-form').waitFor({state:'detached'});}
 if(await page.locator('#modal-root>[data-surface-state=active] .account-modal').count())return;
 await page.locator('[data-hub-page=profile]').click();await page.locator('[data-profile-account]').click();
}

test('cloud account: optional launch, two isolated clients, remembered login and local logout',{timeout:40000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..'));
 const browser=await (process.env.LAB_ENGINE==='webkit'?require('playwright-core').webkit:chromium).launch(process.env.LAB_ENGINE==='webkit'?{headless:true}:{headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']}).catch(async error=>{await server.close();throw error;});
 const a=await browser.newContext({viewport:{width:390,height:740}}),b=await browser.newContext({viewport:{width:390,height:740}}),requests=[],errors=[];
 const userGates=new Map(),pendingGates=new Set(),holdUser=context=>{let start,release;const gate={started:new Promise(r=>start=r),wait:new Promise(r=>release=r),start,release:()=>{if(userGates.get(context)===gate)userGates.delete(context);pendingGates.delete(gate);release();}};userGates.set(context,gate);pendingGates.add(gate);return gate;};
 try{
  for(const [context,name] of [[a,'Алиса'],[b,'Борис']]){
   await context.addInitScript(name=>{if(!localStorage.getItem('playroom.player-profile.v1'))localStorage.setItem('playroom.player-profile.v1',JSON.stringify({version:1,id:name,name,createdAt:1,updatedAt:1}));},name);
   let profile={id:'account-alice',nickname:name,username:'alice'};
   await installProvider(context,accountSyncRoute(async route=>{
    const r=route.request();requests.push({url:r.url(),body:r.postData()});if(r.url().includes('/auth/v1/user')&&userGates.has(context)){const gate=userGates.get(context);userGates.delete(context);gate.start();await gate.wait;}
    const user={id:'account-alice',email:'alice@example.test',is_anonymous:false};
    const body=r.postDataJSON()||{};let data={};
    if(r.url().includes('/auth/'))data=r.url().includes('/user')?user:r.url().includes('/logout')?{}:{user,access_token:'private-access',refresh_token:'private-refresh',expires_in:3600};
    else if(r.url().endsWith('/playroom_social')){if(body.p_action==='profile')profile={...profile,...body.p_data};data=body.p_action==='profile'?profile:{profile,friends:[],rooms:[],invitations:[]};}
    else if(r.url().endsWith('/playroom_online'))data=body.p_action==='group-list'?{groups:[]}:['inbox','group-inbox'].includes(body.p_action)?{cursor:'0',messages:[]}:{friends:[],conversations:[],groups:[],rooms:[],invitations:[]};
    else if(r.url().endsWith('/playroom_cloud_saves_rpc'))data={saves:[],used:0};
    await route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(data)});
   }));
  }
  const pa=await a.newPage(),pb=await b.newPage();for(const p of [pa,pb]){p.setDefaultTimeout(5000);p.on('pageerror',e=>errors.push(e.message));}
  await Promise.all([pa.goto(server.url),pb.goto(server.url)]);
  const localBefore=await pa.evaluate(()=>localStorage.getItem('playroom.player-profile.v1'));
  assert.equal(requests.length,0,'startup does not depend on cloud');
  await pa.locator('[data-hub-page=profile]').click();assert(await pa.locator('#hub-profile-page [data-command=settings]').isVisible());await pa.locator('#hub-profile-page [data-profile-account]').click();
  await pa.locator('.account-form [name=email]').fill('alice@example.test');await pa.locator('.account-form [name=password]').fill('password123');
  await pa.locator('.account-form button[type=submit]').click();await pa.locator('.account-modal').getByText('alice@example.test',{exact:true}).waitFor();
  await pa.evaluate(()=>{window.profileSummaryBefore=document.querySelector('.profile-summary');window.accountTriggerBefore=document.querySelector('[data-profile-account]');window.profileRootBefore=document.querySelector('#hub-profile-page');});
  await pa.locator('.account-modal .modal-head [data-command=close-modal]').click();
  await pa.locator('.profile-summary').getByText(/Облачный аккаунт/).waitFor();assert.equal(await pa.locator('.profile021-auth').count(),0);
  assert(await pa.evaluate(()=>profileSummaryBefore===document.querySelector('.profile-summary')&&profileRootBefore===document.querySelector('#hub-profile-page')),'identity refresh preserves root and trigger nodes');
  const readyReads=requests.filter(request=>request.url.includes('/auth/v1/user')).length,readyHold=holdUser(a);await pa.locator('#hub-profile-page [data-profile-account]').click();assert.equal(await pa.locator('[data-account-mode=username]').isDisabled(),false,'a server-validated account opens with immediately active navigation');await pa.locator('.account-modal .modal-head [data-command=close-modal]').click();await pa.locator('#hub-profile-page [data-profile-account]').click();assert.equal(await pa.locator('[data-account-mode=username]').isDisabled(),false);assert.equal(requests.filter(request=>request.url.includes('/auth/v1/user')).length,readyReads,'ready Back/reopen sends no redundant user requests');readyHold.release();
  const passwordGate=holdUser(a),passwordReads=requests.filter(request=>request.url.includes('/auth/v1/user')).length;await pa.locator('[data-account-mode=password-change]').click();await pa.locator('[name=current-password]').fill('password123');await pa.locator('[data-account-form=password-change] [name=password]').fill('new-password123');await pa.locator('[data-account-form=password-change] [type=submit]').click();await passwordGate.started;assert(await pa.locator('[data-account-form=password-change] [name=password]').isDisabled(),'real password submit still owns the busy input boundary: '+JSON.stringify(await pa.locator('[data-account-form=password-change] fieldset').evaluate(el=>({disabled:el.disabled,busy:PlayroomAccountUI.service.snapshot().busy,aria:el.closest('.account-content').getAttribute('aria-busy')}))));await pa.locator('[data-account-form=password-change]').evaluate(form=>{form.requestSubmit();form.requestSubmit();});assert.equal(requests.filter(request=>request.url.includes('/auth/v1/user')).length,passwordReads+1,'duplicate busy submits do not revalidate or repeat the write');passwordGate.release();await pa.waitForFunction(()=>!PlayroomAccountUI.service.snapshot().busy);await pa.locator('[data-account-mode=username]').click();
  await pa.locator('[data-account-form=username] [name=nickname]').fill('Алиса новая');await pa.locator('[data-account-form=username] [type=submit]').click();await pa.locator('[data-account-mode=username]').waitFor();
  await pa.locator('.account-modal .modal-head [data-command=close-modal]').click();await pa.locator('.profile-summary strong').filter({hasText:'Алиса новая'}).waitFor();
  assert(await pa.evaluate(()=>document.activeElement===accountTriggerBefore),'account Back restores trigger focus');
  const localAfterRename=await pa.evaluate(()=>localStorage.getItem('playroom.player-profile.v1'));assert.equal(JSON.parse(localAfterRename).id,JSON.parse(localBefore).id);
  assert.equal(await pb.evaluate(()=>PlayroomAccountUI.service.snapshot().kind),'local');
  assert.equal(await pb.evaluate(()=>Object.keys(localStorage).filter(k=>k.startsWith('playroom.cloud-auth.')).length),0);
  const snapshot=await pa.evaluate(()=>PlayroomAccountUI.service.snapshot());assert(!JSON.stringify(snapshot).includes('private'));
  const coldHold=holdUser(a),coldReads=requests.filter(request=>request.url.includes('/auth/v1/user')).length;await pa.reload();await pa.locator('[data-hub-page=profile]').click();assert(await pa.locator('#hub-profile-page [data-command=settings]').isVisible());await pa.locator('#hub-profile-page [data-profile-account]').click();await coldHold.started;assert(await pa.locator('[data-account-mode=username]').isDisabled(),'cold stored identity is still validated before actions');await pa.locator('.account-modal .modal-head [data-command=close-modal]').click();await pa.locator('#hub-profile-page [data-profile-account]').click();assert(await pa.locator('[data-account-mode=username]').isDisabled());assert.equal(requests.filter(request=>request.url.includes('/auth/v1/user')).length,coldReads+1,'Back/reopen during cold validation does not duplicate its request');coldHold.release();await pa.waitForFunction(()=>!PlayroomAccountUI.service.snapshot().busy);assert.equal(await pa.locator('[data-account-mode=username]').isDisabled(),false);await pa.locator('.account-modal').getByText('alice@example.test',{exact:true}).waitFor();
  await pa.locator('.account-modal [data-account-mode=logout]').click();await pa.locator('[data-confirm-cancel]').click();assert.equal(await pa.evaluate(()=>PlayroomAccountUI.service.snapshot().kind),'account','cancelled footer logout retains the account');
  await pa.locator('#modal-root>[data-surface-state=active] [data-account-mode=logout]').click();console.log('account logout reentry',JSON.stringify(await pa.evaluate(()=>({busy:PlayroomAccountUI.service.snapshot().busy,frames:[...document.querySelectorAll('#modal-root>[data-surface-state]')].map(el=>({state:el.dataset.surfaceState,confirm:!!el.querySelector('[data-confirm-accept]'),account:!!el.querySelector('.account-content')})),exits:document.querySelectorAll('[data-ui-surface-exit]').length}))));await pa.locator('#modal-root>[data-surface-state=active] [data-confirm-accept]').click();await pa.locator('.account-form [name=email]').waitFor();assert.equal(await pa.locator('#hub-profile-page [data-account-logout]').count(),0,'logout lives only in the common account menu');
  assert.equal(await pa.evaluate(()=>PlayroomAccountUI.service.snapshot().kind),'local');assert.equal(await pa.evaluate(()=>localStorage.getItem('playroom.player-profile.v1')),localAfterRename);
  await pa.locator('.account-modal .modal-head [data-command=close-modal]').click();await pa.locator('.profile-summary').getByText('Войти в облако',{exact:true}).waitFor();assert.equal(await pa.locator('.profile-summary strong').innerText(),'Алиса новая');
  assert.deepEqual(errors,[]);
 }finally{for(const gate of pendingGates)gate.release();await browser.close();await server.close();}
});
test('cloud account: recovery callback survives reload and opens password form',{timeout:30000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..')),browser=await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']}).catch(async error=>{await server.close();throw error;});
 const context=await browser.newContext({viewport:{width:390,height:740}}),page=await context.newPage();page.setDefaultTimeout(5000);
 try{
  await installProvider(context,route=>{
   const r=route.request(),user={id:'account-1',email:'alice@example.test'};
   return route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(r.url().includes('/recover')?{}:r.url().endsWith('/user')?user:{user,access_token:'private-access',refresh_token:'private-refresh',expires_in:3600})});
  });
  await page.goto(server.url);await page.evaluate(()=>{localStorage.setItem('playroom.player-profile.v1',JSON.stringify({version:1,id:'local',name:'Игрок',createdAt:1,updatedAt:1}));});await page.reload();
  await openProfileAccount(page);await page.locator('[data-account-mode=recover]').click();
  await page.locator('[name=email]').fill('alice@example.test');await page.locator('.account-form button[type=submit]').click();await page.locator('[role=status]').filter({hasText:'письмо для восстановления отправлено'}).waitFor();
  await page.goto(server.url+'?code=recovery-code');await page.locator('[data-account-form=password]').waitFor();assert(!page.url().includes('code='));
  await page.reload();await openProfileAccount(page);await page.locator('[data-account-form=password]').waitFor();
  await page.locator('[data-account-form=password] [name=password]').fill('new-password123');await page.locator('.account-form button[type=submit]').click();await page.getByText('Пароль обновлён.',{exact:true}).waitFor();
 }finally{await browser.close();await server.close();}
});
test('cloud account: profile identity follows saved login, request errors and offline return',{timeout:30000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..')),browser=await (process.env.LAB_ENGINE==='webkit'?require('playwright-core').webkit:chromium).launch(process.env.LAB_ENGINE==='webkit'?{headless:true}:{headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']});
 const context=await browser.newContext({viewport:{width:390,height:740}}),page=await context.newPage();page.setDefaultTimeout(5000);const modal=()=>page.locator('#modal-root>[data-surface-state=active] .account-modal');let release,first=true,requestStarted,requestGate=new Promise(resolve=>requestStarted=resolve);
 try{
  await installProvider(context,async route=>{const r=route.request();if(!r.url().includes('/auth/'))return route.fulfill({status:200,json:{profile:null,friends:[],conversations:[],rooms:[],invitations:[]}});if(first){first=false;await new Promise(resolve=>{release=resolve;requestStarted();});return route.fulfill({status:503,json:{}});}const user={id:'a',email:'alice@example.test'};return route.fulfill({status:200,json:r.url().endsWith('/user')?user:{user,access_token:'test',refresh_token:'test',expires_in:3600}});});
  await page.goto(server.url);await openProfileAccount(page);await modal().locator('[name=email]').fill('alice@example.test');await modal().locator('[name=password]').fill('password123');await modal().locator('.account-form [type=submit]').click();await modal().locator('.account-content[aria-busy=true]').waitFor();
  await requestGate;assert(release);await modal().locator('.modal-head [data-command=close-modal]').click();await openProfileAccount(page);assert.equal(await modal().locator('[name=email]').inputValue(),'','new dialog starts with fresh inputs');release();await page.waitForFunction(()=>!PlayroomAccountUI.service.snapshot().busy);assert.equal(await modal().locator('.account-message').innerText(),'','old failed login must not contaminate a reopened dialog');assert.equal(await modal().locator('[name=password]').inputValue(),'');
  first=true;release=null;requestGate=new Promise(resolve=>requestStarted=resolve);await modal().locator('[name=email]').fill('alice@example.test');await modal().locator('[name=password]').fill('password123');await modal().locator('.account-form [type=submit]').click();await modal().locator('.account-content[aria-busy=true]').waitFor();
  await requestGate;assert(release);release();await modal().locator('.account-message[role=alert]').waitFor();assert.equal(await modal().locator('[name=email]').inputValue(),'alice@example.test');
  await modal().locator('.account-form [type=submit]').click();await page.locator('.account-modal').getByText('alice@example.test',{exact:true}).waitFor();await modal().locator('.modal-head [data-command=close-modal]').click();await page.locator('.profile-summary').getByText(/Облачный аккаунт/).waitFor();assert.equal(await page.evaluate(()=>PlayroomAccountUI.service.snapshot().email),'alice@example.test');
  for(const width of [360,390,679]){await page.setViewportSize({width,height:740});assert(await page.locator('.profile-summary').evaluate(e=>e.scrollWidth<=e.clientWidth+1),'profile identity remains readable');}
  await page.reload();await page.locator('[data-hub-page=profile]').click();await page.locator('.profile-summary').getByText(/Облачный аккаунт/).waitFor();assert.equal(await page.evaluate(()=>PlayroomAccountUI.service.snapshot().email),'alice@example.test');
  await context.setOffline(true);assert.equal(await page.evaluate(()=>PlayroomAccountUI.service.snapshot().kind),'account','temporary offline does not log out the saved account');assert.match(await page.locator('.profile-summary small').innerText(),/Облачный аккаунт/);await context.setOffline(false);
 }finally{release?.();await browser.close();await server.close();}
});
test('cloud account: failed first attempt retains the form and retries with one click',{timeout:20000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..')),browser=await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']}).catch(async error=>{await server.close();throw error;});
 const context=await browser.newContext({viewport:{width:390,height:740}}),page=await context.newPage();page.setDefaultTimeout(5000);let attempts=0;
 try{
  await installProvider(context,route=>{if(!new URL(route.request().url()).pathname.endsWith('/token'))return route.fulfill({status:200,contentType:'application/json',body:JSON.stringify({profile:null,friends:[],rooms:[],invitations:[]})});attempts++;return route.fulfill({status:attempts===1?503:200,contentType:'application/json',body:JSON.stringify(attempts===1?{message:'unavailable'}:{user:{id:'a',email:'alice@example.test'},access_token:'test-access',refresh_token:'test-refresh',expires_in:3600})});});
  await page.goto(server.url);await openProfileAccount(page);
  const form=page.locator('.account-form');await form.locator('[name=email]').fill('alice@example.test');await form.locator('[name=password]').fill('password123');
  await page.evaluate(()=>{window.accountFormBefore=document.querySelector('.account-form');});
  await form.locator('[type=submit]').click();await page.locator('.account-message[role=alert]').waitFor();
  assert.equal(await form.locator('[name=email]').inputValue(),'alice@example.test');assert.equal(await form.locator('[name=password]').inputValue(),'password123');
  assert(await page.evaluate(()=>window.accountFormBefore===document.querySelector('.account-form')));
  await form.locator('[type=submit]').click();await page.getByText('alice@example.test',{exact:true}).waitFor();assert.equal(attempts,2);
 }finally{await browser.close();await server.close();}
});
