 const safeNetworks=[];const ids={a:'00000000-0000-4000-8000-000000000001',b:'00000000-0000-4000-8000-000000000002',c:'00000000-0000-4000-8000-000000000003'},names={a:'Алиса',b:'Борис',c:'Михаил'},profiles={},friends=[],rooms=[],invites=[],requests=[],errors=[],pages={},contexts={},onlineSeen=new Set(),chatMessages=[],groups=[],groupInvites=[],groupMessages=[];
 const socialStarted=Date.now();let unreadOverride=null;const chatReads=[];const rid='00000000-0000-4000-8000-000000000020';let failLobby=true,groupFailure=false,groupReads={a:0,b:0},profileWrites=0,settingsReads=0;let passwordEnabled=true,password='AB23CD',visibility='hidden',extraFriends=0,allowPlayerInvites=false,roomCode=null;
 const contacts=k=>[...new Set(chatMessages.filter(m=>m.sender===k||m.recipient===k).map(m=>m.sender===k?m.recipient:m.sender))].map(other=>{const edge=friends.find(f=>(f.sender===k&&f.recipient===other)||(f.recipient===k&&f.sender===other));return{id:edge?'edge':null,userId:ids[other],nickname:names[other],username:profiles[other]?.username,accepted:!!edge?.accepted,requested:!!edge,incoming:edge?.recipient===k,avatar:'star-blue',online:onlineSeen.has(other)};});
