 const list=k=>({conversations:contacts(k),profile:profiles[k]||null,friends:friends.filter(f=>f.sender===k||f.recipient===k).map(f=>{const other=f.sender===k?f.recipient:f.sender;return{id:'edge',userId:ids[other],nickname:names[other],username:profiles[other]?.username,accepted:f.accepted,incoming:f.recipient===k,avatar:'star-blue',game:other==='a'?'UNO':null,online:onlineSeen.has(other)};}),rooms:rooms.filter(r=>r.members.includes(k)).map(r=>({id:r.id,name:r.name,ownerId:ids.a})),invitations:invites.filter(i=>i.target==='b'&&k==='b'&&!i.used&&!i.revoked).map(i=>({id:i.id,roomName:'Игра с Алисой',fromName:names.a}))});
