    assert.equal(await form.evaluate(f=>f.nextElementSibling.textContent),'');assert.equal(await form.locator('[type=submit]').getAttribute('aria-label'),'Отправить');
    if(fail){assert.equal(await form.locator('textarea').inputValue(),body,'failed ACK preserves draft');assert(await form.evaluate(f=>{const old=window.pendingComposer,e=f.querySelector('[data-chat-editor]');return e===old.editor&&e.firstChild===old.node&&e.getBoundingClientRect().height===old.height&&e.scrollTop===old.scroll&&document.getSelection().toString()===old.selection;}),'error feedback preserves exact editor, selection and scroll');assert.equal(await form.locator('[type=submit]').isEnabled(),true);await form.locator('[type=submit]').click();await page.waitForFunction(selector=>document.querySelector(selector)?.elements.message.value==='',active+(kind==='dm'?'[data-chat-form]':'[data-room-chat-form]'));const attempts=calls.filter(c=>c.action===sendAction&&c.data.body===body);assert.equal(attempts.length,2);assert.equal(attempts[0].data.nonce??attempts[0].data.id,attempts[1].data.nonce??attempts[1].data.id,'explicit retry preserves idempotency key');}
