test('cloud account: inner Back returns one level and retires late form feedback',{timeout:50000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..')),browser=await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']}).catch(async error=>{await server.close();throw error;}),context=await browser.newContext({viewport:{width:390,height:844},reducedMotion:'reduce'}),page=await context.newPage(),errors=[];
 page.setDefaultTimeout(5000);page.on('pageerror',error=>errors.push(error.message));let holdList=null,holdPassword=null,puts=0;
 const gate=()=>{let start,release,finish;return {started:new Promise(r=>start=r),wait:new Promise(r=>release=r),finished:new Promise(r=>finish=r),start:()=>start(),release:()=>release(),finish:()=>finish()};};
 const active=()=>page.locator('#modal-root>[data-surface-state=active]'),account=()=>active().locator('.account-modal');
 try{
  await installProvider(context,accountSyncRoute(async route=>{
   const request=route.request(),url=request.url(),data=request.postDataJSON()||{},user={id:'account-back',email:'back@example.test'},profile={userId:user.id,nickname:'Игрок',username:'back_user'};
   if(url.includes('/auth/')){if(request.method()==='PUT'){puts++;if(holdPassword){const own=holdPassword;own.start();await own.wait;await route.fulfill({status:503,json:{message:'unavailable'}});own.finish();return;}}return route.fulfill({json:url.endsWith('/user')?user:url.includes('/recover')||url.includes('/logout')?{}:{user,access_token:'fixture-access',refresh_token:'fixture-refresh',expires_in:3600}});}
   if(url.endsWith('/playroom_social')){if(data.p_action==='list'&&holdList){const own=holdList;own.start();await own.wait;await route.fulfill({status:503,json:{message:'unavailable'}});own.finish();return;}return route.fulfill({json:{profile,friends:[],rooms:[],invitations:[]}});}
   if(url.endsWith('/playroom_cloud_saves_rpc'))return route.fulfill({json:{saves:[],used:0}});
   return route.fulfill({json:{friends:[],conversations:[],groups:[],rooms:[],invitations:[],messages:[],cursor:'0'}});
  }));
  await page.goto(server.url);await openProfileAccount(page);await account().locator('[name=email]').fill('back@example.test');await account().locator('[name=password]').fill('old-password123');await account().locator('[type=submit]').click();await account().locator('[data-account-mode=username]').waitFor();await page.waitForFunction(()=>!PlayroomSocialUI.service.busy);
  await page.evaluate(()=>{window.backAccountFrame=document.querySelector('#modal-root>[data-surface-state=active]');window.backProfileRoot=document.querySelector('#hub-profile-page');});
  await account().locator('[data-account-mode=username]').click();await account().locator('[data-account-form=username] [name=nickname]').fill('Несохранённое имя');await account().locator('.modal-head [data-command=close-modal]').click();
  assert.equal(await account().count(),1,'top Back returns to account overview, not Parameters');assert(await page.evaluate(()=>backAccountFrame===document.querySelector('#modal-root>[data-surface-state=active]')),'internal Back retains the account surface');await account().locator('[data-account-mode=username]').waitFor();assert.equal(await account().locator('[data-account-form]').count(),0);
  await account().locator('.modal-head [data-command=close-modal]').click();assert(await page.locator('#hub-profile-page.is-active').isVisible());assert(await page.evaluate(()=>backProfileRoot===document.querySelector('#hub-profile-page')),'second Back returns to the exact Parameters DOM');
  await page.locator('[data-profile-account]').click();await account().locator('[data-account-mode=password-change]').click();await account().locator('[name=current-password]').fill('old-password123');await account().locator('[name=password]').fill('discarded-secret123');await page.keyboard.press('Escape');await account().locator('[data-account-mode=password-change]').waitFor();assert.equal(await account().locator('input[type=password]').count(),0);await account().locator('[data-account-mode=password-change]').click();assert.equal(await account().locator('[name=current-password]').inputValue(),'');assert.equal(await account().locator('[name=password]').inputValue(),'');
  await page.evaluate(()=>PlayroomAppBridge.closeModal());await account().locator('[data-account-mode=recover]').click();await account().locator('[data-account-form=recover]').waitFor();await page.evaluate(()=>PlayroomAppBridge.closeModal());await account().locator('[data-account-mode=recover]').waitFor();assert.equal(await account().locator('[data-account-form]').count(),0,'public close follows the same one-level contract for signed-in recovery');
  holdList=gate();await account().locator('[data-account-mode=username]').click();await holdList.started;await account().locator('.modal-head [data-command=close-modal]').click();await account().locator('[data-account-mode=password-change]').click();const form=account().locator('[data-account-form=password-change]'),input=form.locator('[name=password]');await input.fill('retained-secret123');await input.focus();await input.evaluate(node=>{node.setSelectionRange(2,6);window.backPasswordInput=node;});const oldList=holdList;holdList=null;oldList.release();await oldList.finished;await page.waitForFunction(()=>!PlayroomSocialUI.service.busy);assert.equal(await input.inputValue(),'retained-secret123');assert(await page.evaluate(()=>backPasswordInput===document.activeElement&&backPasswordInput.selectionStart===2&&backPasswordInput.selectionEnd===6));assert.equal(await account().locator('.account-message[role=alert]').count(),0,'a retired username read cannot report errors in the new password form');
  await form.locator('[name=current-password]').fill('old-password123');holdPassword=gate();await form.locator('[type=submit]').click();await holdPassword.started;assert(await input.isDisabled());const firstControl=account().locator('.surface-head-actions button').first();await firstControl.focus();await page.keyboard.press('Shift+Tab');assert(await account().locator('[data-command=profile-edit]').evaluate(node=>node===document.activeElement),'busy fieldset controls are excluded from the modal focus trap');await form.evaluate(node=>{node.requestSubmit();node.requestSubmit();});assert.equal(puts,1,'busy duplicate submits cannot issue a second password write');await account().locator('.modal-head [data-command=close-modal]').click();await account().locator('[data-account-mode=password-change]').waitFor();assert.equal(await account().locator('input[type=password]').count(),0);assert(await account().locator('[data-account-mode=password-change]').isDisabled(),'Back never bypasses the real credential operation');const oldPassword=holdPassword;holdPassword=null;oldPassword.release();await oldPassword.finished;await page.waitForFunction(()=>!PlayroomAccountUI.service.snapshot().busy);assert.equal(await account().locator('.account-message[role=alert]').count(),0);await account().locator('[data-account-mode=password-change]').click();assert.equal(await account().locator('[name=password]').inputValue(),'');await page.keyboard.press('Escape');await account().locator('[data-account-mode=password-change]').waitFor();await page.keyboard.press('Escape');assert(await page.locator('#hub-profile-page.is-active').isVisible());assert.deepEqual(errors,[]);
 }finally{holdList?.release();holdPassword?.release();await browser.close();await server.close();}
});

test('chat editor: native undo redo plain rich paste multiline and composition preserve draft',{timeout:30000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..')),browser=await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']}),context=await browser.newContext({viewport:{width:390,height:844}}),page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));
 await context.route(/^https?:\/\/(?!127\.0\.0\.1:)/,r=>r.abort());
 try{
  await page.goto(server.url);await page.locator('.game-tile').first().waitFor();
  await page.evaluate(()=>{PlayroomAppBridge.openModal(PlayroomGameScreen.modalHead('Редактор')+'<div data-editor-proof>'+PlayroomChatComponents.composer('proof')+'</div>','chat-modal');const f=document.querySelector('[data-proof-form]');PlayroomChatComponents.resize(f);f.addEventListener('input',()=>PlayroomChatComponents.resize(f));});
  const editor=page.locator('[data-chat-editor]'),value=()=>page.locator('[data-proof-form] textarea').inputValue();
  await editor.focus();await editor.pressSequentially('hello');await editor.press('Control+z');assert.notEqual(await value(),'hello','native Undo changes typed text (browser owns transaction grouping)');await editor.press('Control+Shift+z');assert.equal(await value(),'hello','native Redo restores typed text');
  await editor.fill('0123456789');await editor.evaluate(e=>getSelection().setBaseAndExtent(e.firstChild,2,e.firstChild,8));await editor.press('Backspace');assert.equal(await value(),'0189');await editor.press('Control+z');assert.equal(await value(),'0123456789','native Undo restores a deleted selection');
  await editor.fill('base');await editor.press('End');await page.evaluate(()=>PlayroomChatComposer.insert(document.querySelector('[data-proof-form]'),':nice:'));assert.equal(await value(),'base:nice:');assert.equal(await editor.locator('[data-reaction-token=":nice:"]').count(),1);await editor.press('Control+z');assert.equal(await value(),'base','reaction insertion is undoable');await editor.press('Control+Shift+z');assert.equal(await value(),'base:nice:','reaction redo restores portable shortcode');
  await editor.pressSequentially('x');await editor.press('Control+z');assert.equal(await value(),'base:nice:','typing beside a rich token is undoable');await editor.evaluate(e=>{const r=document.createRange();r.selectNode(e.querySelector('[data-reaction-token]'));getSelection().removeAllRanges();getSelection().addRange(r);});await editor.press('Backspace');assert.equal(await value(),'base');await editor.press('Control+z');assert.equal(await value(),'base:nice:','rich token deletion is undoable');assert.equal(await editor.locator('[data-reaction=nice]').count(),1);
  await editor.fill('');await editor.pressSequentially(':nice:');assert.equal(await editor.locator('[data-reaction=nice]').count(),1,'typed shortcode renders art');await editor.press('Control+z');assert(await editor.locator('[data-reaction=nice]').count()===0||await value()!==':nice:','undo reverses shortcode formatting or typing');await editor.press('Control+Shift+z');assert.equal(await value(),':nice:');assert.equal(await editor.locator('[data-reaction=nice]').count(),1);
  await editor.fill('base');await editor.press('End');await editor.evaluate(e=>{const data=new DataTransfer();data.setData('text/plain','\nline :time: <img src=x onerror=alert(1)>');data.setData('text/html','<img src=x onerror=alert(1)>');e.dispatchEvent(new ClipboardEvent('paste',{bubbles:true,cancelable:true,clipboardData:data}));});assert.equal(await value(),'base\nline :time: <img src=x onerror=alert(1)>');assert.equal(await editor.locator('img').count(),0);assert.equal(await editor.locator('[data-reaction=time]').count(),1);await editor.press('Control+z');assert.equal(await value(),'base','safe multiline rich paste is one undoable insertion');await editor.press('Control+Shift+z');assert.match(await value(),/line :time: <img/);
  await editor.fill('line');await editor.press('End');await editor.press('Shift+Enter');await editor.pressSequentially('two');assert.equal(await value(),'line\ntwo');await editor.press('Control+z');assert(!String(await value()).includes('two'),'multiline typing can be undone');await editor.press('Control+Shift+z');assert.equal(await value(),'line\ntwo');
  await editor.fill('');await editor.evaluate(e=>{e.dispatchEvent(new CompositionEvent('compositionstart',{bubbles:true,data:''}));document.execCommand('insertText',false,'かな');window.compositionTextNode=e.firstChild;e.dispatchEvent(new InputEvent('input',{bubbles:true,isComposing:true,inputType:'insertCompositionText',data:'かな'}));});assert.equal(await editor.evaluate(e=>e.firstChild===compositionTextNode),true,'composition input retains native text node');await editor.evaluate(e=>e.dispatchEvent(new CompositionEvent('compositionend',{bubbles:true,data:'かな'})));assert.equal(await value(),'かな');assert.equal(await editor.evaluate(e=>e.firstChild===compositionTextNode),true);await editor.press('Control+z');assert.notEqual(await value(),'かな','composition fixture native edit remains undoable (browser owns grouping)');await editor.press('Control+Shift+z');assert.equal(await value(),'かな');
  await editor.fill('x'.repeat(1999));await editor.press('End');await page.evaluate(()=>PlayroomChatComposer.insert(document.querySelector('[data-proof-form]'),'abc'));assert.equal((await value()).length,2000);await editor.press('Control+z');assert.equal((await value()).length,1999);
  await editor.fill('x'.repeat(2000));await editor.press('End');await editor.press('Shift+Enter');assert.equal((await value()).length,2000,'native line break also respects the length boundary');
  await editor.fill('Жду :time: <img src=x onerror=alert(1)>');assert.equal(await editor.locator('[data-reaction=time]').count(),1);assert.equal(await editor.locator('img').count(),0,'native whole-text replacement uses safe rich markup');
  await editor.fill('x'.repeat(1999));await editor.press('End');await editor.evaluate(e=>{e.dispatchEvent(new CompositionEvent('compositionstart',{bubbles:true}));document.execCommand('insertText',false,'かな');e.dispatchEvent(new CompositionEvent('compositionend',{bubbles:true,data:'かな'}));});assert.equal((await value()).length,2001,'uncancelable composition preserves the entire visible draft');assert.equal(await editor.textContent(),await value());assert.equal(await page.locator('[data-proof-form] [type=submit]').isDisabled(),true);assert.equal(await editor.getAttribute('aria-invalid'),'true');assert.match(await page.locator('[data-chat-send-state]').textContent(),/2000/);await editor.press('Backspace');assert.equal((await value()).length,2000);assert.equal(await page.locator('[data-proof-form] [type=submit]').isEnabled(),true);assert.equal(await editor.getAttribute('aria-invalid'),null);
  await editor.fill('drop safe');await editor.evaluate(e=>{const event=new DragEvent('drop',{bubbles:true,cancelable:true});e.dispatchEvent(event);window.dropWasPrevented=event.defaultPrevented;});assert.equal(await page.evaluate(()=>dropWasPrevented),true);assert.equal(await value(),'drop safe');assert.deepEqual(errors,[]);
 }finally{await browser.close();await server.close();}
});

test('chat message gestures: selection survives swipe and fresh tap bypasses release suppression',{timeout:30000},async()=>{
 const server=await serveBrowserFixture(path.resolve(__dirname,'..')),browser=await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']}),context=await browser.newContext({viewport:{width:390,height:844}}),page=await context.newPage();await context.route(/^https?:\/\/(?!127\.0\.0\.1:)/,r=>r.abort());
 try{
  await page.goto(server.url);await page.locator('.game-tile').first().waitFor();await page.evaluate(()=>{PlayroomAppBridge.openModal(PlayroomGameScreen.modalHead('Сообщения')+'<div id="gesture-proof"><div class="chat-message" data-entity="message-1"><p>Длинное сообщение для выделения текста</p></div><div class="chat-message" data-entity="message-2"><p>Следующее сообщение</p></div></div>','chat-modal');const host=document.querySelector('#gesture-proof');window.gestureReplies=[];window.gestureClicks=[];PlayroomChatComponents.bindActions(host,id=>({id,body:'text'}),{reply:m=>gestureReplies.push(m.id)});host.addEventListener('click',event=>{const m=PlayroomChatComponents.messageTarget(event,host);if(m)gestureClicks.push(m.dataset.entity);});});
  const result=await page.evaluate(()=>{const first=document.querySelector('#gesture-proof .chat-message'),second=first.nextElementSibling,text=first.querySelector('p').firstChild;const pointer=(type,x)=>first.dispatchEvent(new PointerEvent(type,{bubbles:true,pointerId:1,pointerType:'touch',isPrimary:true,button:0,clientX:x,clientY:100}));getSelection().setBaseAndExtent(text,1,text,9);const selected=getSelection().toString();pointer('pointerdown',250);pointer('pointerup',100);const selectionResult={selected:getSelection().toString(),replies:gestureReplies.length};getSelection().removeAllRanges();pointer('pointerdown',250);pointer('pointerup',100);first.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true,detail:1,clientX:100,clientY:100}));const compatibility=gestureClicks.length;second.dispatchEvent(new PointerEvent('pointerdown',{bubbles:true,pointerId:2,pointerType:'touch',isPrimary:true,button:0,clientX:200,clientY:200}));second.dispatchEvent(new PointerEvent('pointerup',{bubbles:true,pointerId:2,pointerType:'touch',isPrimary:true,button:0,clientX:200,clientY:200}));second.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true,detail:1,clientX:200,clientY:200}));second.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true,detail:0}));return {selected,selectionResult,replies:gestureReplies,compatibility,clicks:gestureClicks};});
  assert.equal(result.selectionResult.selected,result.selected);assert.equal(result.selectionResult.replies,0,'text selection must not become reply');assert.deepEqual(result.replies,['1']);assert.equal(result.compatibility,0,'only completed swipe compatibility click is consumed');assert.deepEqual(result.clicks,['message-2','message-2'],'fresh pointer and keyboard activation remain independent');
 }finally{await browser.close();await server.close();}
});


